  'pet.renombrada': T('Título cambiado. El contenido y tu progreso no cambian.', 'Title changed. The content and your progress do not change.', 'Titel geändert. Inhalt und Fortschritt bleiben gleich.', 'Titre modifié. Le contenu et votre progression ne changent pas.', 'Titolo cambiato. Il contenuto e i tuoi progressi non cambiano.'),
  'pet.tituloInvalido': T('Escribe un título de 1 a {max} caracteres.', 'Write a title of 1 to {max} characters.', 'Gib einen Titel mit 1 bis {max} Zeichen ein.', 'Saisissez un titre de 1 à {max} caractères.', 'Scrivi un titolo da 1 a {max} caratteri.'),
